(29561, 'John 5:10', 'John', 5, 10, 'نو د یهودیانو مشرانو هغه روغ شوي سړي ته وویل: «دا د سبت ورځ ده، د سبت په ورځ تاته روا نه ده چې خپله بستره یوسې.»', 'نو د یهودیانو مشرانو هغه روغ شوی سری ته وویل: «دا د سبت ورج ده، د سبت په ورج تاته روا نه ده چې خپله بستره یوسې.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_5_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237835, 1761237835),
(29562, 'John 5:11', 'John', 5, 11, 'خو هغه ځواب ورکړ: «کوم سړي چې زه روغ کړم ماته یې وویل چې خپله بستره دې واخله او وګرځه.»', 'خو هغه جواب ورکر: «کوم سری چې زه روغ کرم ماته یې وویل چې خپله بستره دې واخله او وګرجه.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_5_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(29563, 'John 5:12', 'John', 5, 12, 'هغوی د هغه نه پوښتنه وکړه: «هغه سړی څوک دی چې تاته یې وویل چې بستره دې واخله او وګرځه؟»', 'هغوی د هغه نه پوشتنه وکره: «هغه سری چوک دی چې تاته یې وویل چې بستره دې واخله او وګرجه؟»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_5_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(29564, 'John 5:13', 'John', 5, 13, 'خو هغه سړی چې روغ شوی ؤ نه پوهېده چې عیسی څوک دی، ځکه چې په هغه ځای کې ډېره ګڼه‌ګوڼه وه او عیسی ځان ویستلی ؤ.', 'خو هغه سری چې روغ شوی و نه پوهېده چې عیسی چوک دی، جکه چې په هغه جای کې دېره ګنه‌ګونه وه او عیسی جان ویستلی و.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_5_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(29565, 'John 5:14', 'John', 5, 14, 'وروسته بیا عیسی هغه سړی د خدای په کور کې پیدا کړ او ورته ویې ویل: «ګوره، اوس چې ښه شوی یې نو نوره ګناه مه کوه، که نه نو د دې نه به هم د زیاتو کړاوونو سره مخ شې.»', 'وروسته بیا عیسی هغه سری د خدای په کور کې پیدا کر او ورته ویې ویل: «ګوره، اوس چې شه شوی یې نو نوره ګناه مه کوه، که نه نو د دې نه به هم د زیاتو کراوونو سره مخ شې.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_5_14.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237835, 1761237835),
(29566, 'John 5:15', 'John', 5, 15, 'هغه سړی لاړ او د یهودیانو مشرانو ته یې خبر ورکړ: «چا چې زه روغ کړی وم هغه عیسی ؤ.»', 'هغه سری لار او د یهودیانو مشرانو ته یې خبر ورکر: «چا چې زه روغ کری وم هغه عیسی و.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_5_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237835, 1761237835),
(29567, 'John 5:16', 'John', 5, 16, 'په دې خاطر چې عیسی د سبت په ورځ داسې کارونه کول، نو د یهودیانو مشرانو د هغه په ځورولو پیل وکړ.', 'په دې خاطر چې عیسی د سبت په ورج داسې کارونه کول، نو د یهودیانو مشرانو د هغه په جورولو پیل وکر.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_5_16.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237835, 1761237835),
(29568, 'John 5:17', 'John', 5, 17, 'خو عیسی هغوی ته وویل: «زما پلار تل داسې کارونه کړي دي، نو زه هم همداسې کوم.»', 'خو عیسی هغوی ته وویل: «زما پلار تل داسې کارونه کری دی، نو زه هم همداسې کوم.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_5_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(29569, 'John 5:18', 'John', 5, 18, 'د عیسی په دې خبره د یهودیانو مشرانو هڅه وکړه چې هغه ووژني، ځکه چې یوازې دا نه چې هغه د سبت قانون مات کړی دی بلکې په دې هم چې هغه خدای ته خپل پلار ووایه او په دې ډول یې خپل ځان د خدای سره برابر وګاڼه. د زوی واک او اختیار', 'د عیسی په دې خبره د یهودیانو مشرانو هچه وکره چې هغه ووژنی، جکه چې یوازې دا نه چې هغه د سبت قانون مات کری دی بلکې په دې هم چې هغه خدای ته خپل پلار ووایه او په دې دول یې خپل جان د خدای سره برابر وګانه. د زوی واک او اختیار', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_5_18.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237835, 1761237835),
(29570, 'John 5:19', 'John', 5, 19, 'عیسی هغوی ته په ځواب کې وویل: «په یقین سره زه تاسو ته دا وایم چې زوی نه شي کولای چې له خپله ځانه کوم کار وکړي، بلکې یوازې هغه کار کوي چې هغه یې ویني چې پلار یې کوي. څه چې پلار کوي هغه زوی هم کوي.', 'عیسی هغوی ته په جواب کې وویل: «په یقین سره زه تاسو ته دا وایم چې زوی نه شی کولای چې له خپله جانه کوم کار وکری، بلکې یوازې هغه کار کوی چې هغه یې وینی چې پلار یې کوی. چه چې پلار کوی هغه زوی هم کوی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_5_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(29571, 'John 5:20', 'John', 5, 20, 'ځکه چې زوی په پلار باندې ګران وي او هغه چې خپله کوم کارونه کوي هغه ټول زوی ته ورښایي. برسېره پر‌دې نور لوی لوی کارونه هم ورته وروښایي او تاسو ټول به ورته حیران پاتې شئ.', 'جکه چې زوی په پلار باندې ګران وی او هغه چې خپله کوم کارونه کوی هغه تول زوی ته ورشایی. برسېره پر‌دې نور لوی لوی کارونه هم ورته وروشایی او تاسو تول به ورته حیران پاتې شی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_5_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(29572, 'John 5:21', 'John', 5, 21, 'ځکه لکه څنګه چې پلار مړي راژوندي کوي او هغوی ته ژوند ورکوي، نو په همدې ډول زوی هم چې هرچا ته وغواړي ژوند ورکوي.', 'جکه لکه چنګه چې پلار مری راژوندی کوی او هغوی ته ژوند ورکوی، نو په همدې دول زوی هم چې هرچا ته وغواری ژوند ورکوی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_5_21.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237835, 1761237835),
(29573, 'John 5:22', 'John', 5, 22, 'همدارنګه پلار د هېچا په هکله قضاوت نه کوي بلکې خپل زوی ته یې پوره حق ورکړی دی چې قضاوت وکړي،', 'همدارنګه پلار د هېچا په هکله قضاوت نه کوی بلکې خپل زوی ته یې پوره حق ورکری دی چې قضاوت وکری،', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_5_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(29574, 'John 5:23', 'John', 5, 23, 'ترڅو لکه څنګه چې ټول د پلار درناوی کوي، هماغسې د زوی درناوی هم وکړي. څوک چې د زوی عزت نه کوي، نو د هغه د پلار چې هغه یې رالېږلی دی هم عزت نه کوي.', 'ترچو لکه چنګه چې تول د پلار درناوی کوی، هماغسې د زوی درناوی هم وکری. چوک چې د زوی عزت نه کوی، نو د هغه د پلار چې هغه یې رالېزلی دی هم عزت نه کوی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_5_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(29575, 'John 5:24', 'John', 5, 24, 'په یقین سره زه تاسو ته دا وایم څوک چې زما خبرو ته غوږ نیسی او په هغه چا باندې ایمان راوړي چې زه یې رالېږلی یم، نو هغه تلپاتې ژوندون لري. هغه به محاکمه نه شي، بلکې هغه لا پخوا د مرګ نه تېر شوی او ژوند یې پیل کړی دی.', 'په یقین سره زه تاسو ته دا وایم چوک چې زما خبرو ته غوز نیسی او په هغه چا باندې ایمان راوری چې زه یې رالېزلی یم، نو هغه تلپاتې ژوندون لری. هغه به محاکمه نه شی، بلکې هغه لا پخوا د مرګ نه تېر شوی او ژوند یې پیل کری دی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_5_24.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237835, 1761237835),
(29576, 'John 5:25', 'John', 5, 25, 'په یقین سره زه تاسو ته دا وایم چې هغه وخت به راشي، بلکې راغلی دی چې مړي به د خدای د زوی اواز اوري او هرڅوک یې چې واوري هغه به راژوندی شي.', 'په یقین سره زه تاسو ته دا وایم چې هغه وخت به راشی، بلکې راغلی دی چې مری به د خدای د زوی اواز اوری او هرچوک یې چې واوری هغه به راژوندی شی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_5_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(29577, 'John 5:26', 'John', 5, 26, 'لکه څنګه چې پلار هغه ذات دی چې انسانانو ته ژوند ورکوي، نو زوی ته یې هم دا قدرت ورکړی دی چې انسانانو ته ژوند ورکړي.', 'لکه چنګه چې پلار هغه ذات دی چې انسانانو ته ژوند ورکوی، نو زوی ته یې هم دا قدرت ورکری دی چې انسانانو ته ژوند ورکری.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_5_26.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(29578, 'John 5:27', 'John', 5, 27, 'هغه زوی ته دا واک او اختیار ورکړی دی چې قضاوت وکړي، ځکه چې د انسان زوی دی.', 'هغه زوی ته دا واک او اختیار ورکری دی چې قضاوت وکری، جکه چې د انسان زوی دی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_5_27.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(29579, 'John 5:28', 'John', 5, 28, 'په دې باندې مه حیرانېږئ، ځکه چې هغه وخت به راشي چې ټول مړي به په قبرونو کې د هغه اواز واوري', 'په دې باندې مه حیرانېزی، جکه چې هغه وخت به راشی چې تول مری به په قبرونو کې د هغه اواز واوری', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_5_28.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(29580, 'John 5:29', 'John', 5, 29, 'او د خپلو قبرونو نه به راووځي. کومو خلکو چې نېک کارونه کړي وي هغوی به راپورته شي او ژوند به کوي او کومو خلکو چې بد کارونه کړي دي هغوی به راپورته شي او سزا به ورته ورکول کیږي. د عیسی په هکله شاهدي ورکول', 'او د خپلو قبرونو نه به راووجی. کومو خلکو چې نېک کارونه کری وی هغوی به راپورته شی او ژوند به کوی او کومو خلکو چې بد کارونه کری دی هغوی به راپورته شی او سزا به ورته ورکول کیزی. د عیسی په هکله شاهدی ورکول', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_5_29.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(29581, 'John 5:30', 'John', 5, 30, 'زه په خپل اختیار هېڅ نه شم کولای. زه د خلکو په هکله هغه قضاوت کوم چې د خپل پلار نه یې اورم. نو کله چې د هغوی په هکله قضاوت کوم هغه قضاوت د انصاف له مخې وي، ځکه چې زه خپله رضا نه بلکې د هغه چا رضا پوره کوم چې زه یې رالېږلی یم.', 'زه په خپل اختیار هېچ نه شم کولای. زه د خلکو په هکله هغه قضاوت کوم چې د خپل پلار نه یې اورم. نو کله چې د هغوی په هکله قضاوت کوم هغه قضاوت د انصاف له مخې وی، جکه چې زه خپله رضا نه بلکې د هغه چا رضا پوره کوم چې زه یې رالېزلی یم.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_5_30.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(29582, 'John 5:31', 'John', 5, 31, 'که چېرې زه د خپل ځان په هکله شاهدي ورکړم نو دا شاهدي رښتیا نه ده.', 'که چېرې زه د خپل جان په هکله شاهدی ورکرم نو دا شاهدی رشتیا نه ده.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_5_31.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(29583, 'John 5:32', 'John', 5, 32, 'خو یو بل څوک شته چې زما په هکله شاهدي ورکوي او زه پوهېږم هغه چې زما په هکله شاهدي ورکوي هغه رښتیا دي.', 'خو یو بل چوک شته چې زما په هکله شاهدی ورکوی او زه پوهېزم هغه چې زما په هکله شاهدی ورکوی هغه رشتیا دی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_5_32.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237835, 1761237835),
